using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Diagnostics.HealthChecks;using Footing.Framework.Data;
namespace Footing.Framework.Health;
public sealed class DbHealthCheck(IDbConnectionFactory f):IHealthCheck{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext c,CancellationToken ct=default){try{using var con=f.CreateConnection();if(con is System.Data.Common.DbConnection db)await db.OpenAsync(ct);else con.Open();return HealthCheckResult.Healthy("db ok");}catch(Exception ex){return HealthCheckResult.Unhealthy("db fail",ex);}}}
public sealed class EventBusHealthCheck(EventBus.EventBus b):IHealthCheck{public Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext c,CancellationToken ct=default)=>Task.FromResult(b==null?HealthCheckResult.Unhealthy("bus null"):HealthCheckResult.Healthy("bus ok"));}
public static class FootingHealthChecksExtensions{public static IServiceCollection AddFootingHealthChecks(this IServiceCollection s){s.Add(new ServiceDescriptor(typeof(IHealthCheck),sp=>new DbHealthCheck(sp.GetRequiredService<IDbConnectionFactory>()),ServiceLifetime.Singleton));s.Add(new ServiceDescriptor(typeof(IHealthCheck),sp=>new EventBusHealthCheck(sp.GetService<EventBus.EventBus>()!),ServiceLifetime.Singleton));return s;}}
